{{- /*
  The nginx redirect map for the site's OLD processed-image URLs — `nginxvariantmap`
  output format in hugo.yaml, written to /_nginx/image-variant-redirects.map and
  read by the `map "$legacy_dir$legacy_hu" $legacy_variant_new` block in the
  nginx.conf of Web-Services/homepage and homepage-tor
  (docs/concepts/stable-image-urls.md §5.2).

  Until 2026-10 every processed image was published as `<name>_hu_<hash>.<ext>`,
  under Hugo's cache key, which Hugo moves on its own (it moved every gallery
  variant on 2026-09-10). The build now names each variant itself
  (layouts/partials/image-variant.html), and data/legacyImageVariants.yaml — a
  history computed ONCE from the image cache and frozen — says which new file each
  old hash was. Only proven lines are in it: equal bytes, or the same source with
  exactly one variant of that size and format. An unknown hash stays a 404.

  The KEY is the old directory plus `_hu_<hash>`, without the stem: a gallery
  variant requested under its store name or its slug, `.JPG` or `.jpg`, is the
  same line and one hop. The directory is in it because a page resource's hash
  exists once per language, and each language has its own target.

  Gallery lines store the photo's id and spec directory, and the current file
  slug is looked up here, so a later reworded English title moves the target
  with it instead of breaking the line. A photo that is gone has no line.

  Targets are percent-encoded (book and game covers carry spaces and umlauts in
  their names; nginx writes the value into the Location header as it stands);
  keys are not, because nginx matches them against the decoded $uri. nginx
  matches map strings ignoring case, so a key twice ignoring case stops the
  build. That every target is a served file is a static test
  (tests/static/image-urls.spec.ts), not a check here: a template cannot see
  what the other pages publish.
*/ -}}
{{- $meta := partialCached "gallery-meta.html" . -}}
{{- $data := hugo.Data.legacyImageVariants | default dict -}}
{{- $formats := dict "jpg" "jpg" "jpeg" "jpg" "png" "png" "webp" "webp" "gif" "gif" "tif" "tif" "tiff" "tif" "bmp" "bmp" -}}
{{- /* A scratch map, not `merge`: merge copies the dict on every call, which is
       quadratic over ~7,500 lines. */ -}}
{{- $seen := newScratch -}}
{{- $lines := slice -}}

{{- range $hash, $v := $data.gallery -}}
  {{- $id := index $v 0 -}}
  {{- $dir := index $v 1 -}}
  {{- with index $meta.byId $id -}}
    {{- /* The extension image-variant.html gives the variant: the format a spec
           token names, else the source's own. */ -}}
    {{- $ext := index $formats (strings.TrimPrefix "." (path.Ext .file)) -}}
    {{- range split $dir "-" -}}
      {{- with index $formats . }}{{ $ext = . }}{{ end -}}
    {{- end -}}
    {{- $key := printf "/images/gallery/_hu_%s" $hash -}}
    {{- $target := printf "/images/gallery/%s/%s.%s" $dir .fileSlug $ext -}}
    {{- $seen.SetInMap "keys" (lower $key) true -}}
    {{- $lines = $lines | append (printf "\"%s\" %s;" $key (urls.Parse $target).String) -}}
  {{- end -}}
{{- end -}}

{{- range $key, $target := $data.other -}}
  {{- if not (findRE `^/(?:[^/]+/)*_hu_[0-9a-f]+$` $key) -}}
    {{- errorf "data/legacyImageVariants.yaml: %q is not an old directory plus _hu_<hash>" $key -}}
  {{- end -}}
  {{- if not (strings.HasPrefix $target "/") -}}
    {{- errorf "data/legacyImageVariants.yaml: the target of %q is not a site path: %q" $key $target -}}
  {{- end -}}
  {{- if index ($seen.Get "keys" | default dict) (lower $key) -}}
    {{- errorf "data/legacyImageVariants.yaml: %q is in the map twice (nginx compares keys ignoring case)" $key -}}
  {{- end -}}
  {{- $seen.SetInMap "keys" (lower $key) true -}}
  {{- $q := replace (replace $key `\` `\\`) `"` `\"` -}}
  {{- $lines = $lines | append (printf "\"%s\" %s;" $q (urls.Parse $target).String) -}}
{{- end -}}
# Generated by Hugo from data/legacyImageVariants.yaml (layouts/_default/home.nginxvariantmap.map).
# Old "<dir>/_hu_<hash>" -> the variant's stable path. Do not edit; do not serve.
{{ delimit (sort $lines) "\n" }}
